INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39511, 'Psalms 7:11', 'Psalms', 7, 11, 'خدای دی عادل قاضي بدکاران هره ورځ غندي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_11.mp3', '', 1761754199, 1761754199),
(39512, 'Psalms 7:12', 'Psalms', 7, 12, 'که دوی نه کړلې بدلې خپلې لارې خدای به تېره کړي ورته خپله توره هغه کشوي او تیاروي ورته لینده خپله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_12.mp3', '', 1761754199, 1761754199),
(39513, 'Psalms 7:13', 'Psalms', 7, 13, 'کړي به وژونکې وسله ورته تیاره جوړوي ورته هم غشي سوځوونکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_13.mp3', '', 1761754199, 1761754199),
(39514, 'Psalms 7:14', 'Psalms', 7, 14, 'ګورئ څنګه کوي فکر د بدۍ دا بدکاران جوړوي د ځورولو پلانونه دروغ وایي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_14.mp3', '', 1761754199, 1761754199),
(39515, 'Psalms 7:15', 'Psalms', 7, 15, 'نورو خلکو ته چې دوی کیندي څاګانې شي به په خپله ورګوزار په کې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_15.mp3', '', 1761754199, 1761754199),
(39516, 'Psalms 7:16', 'Psalms', 7, 16, 'ومومي سزا د خپلو بدو به هغه ظلمونه به یې انبار شي په خپل سر باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_16.mp3', '', 1761754199, 1761754199),
(39517, 'Psalms 7:17', 'Psalms', 7, 17, 'شکر به وکړم له څښتنه د انصاف دپاره څښتن تعالی ته به ثنا وایمه په سندرو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms7_verse_17.mp3', '', 1761754199, 1761754199),
(39518, 'Psalms 96:1', 'Psalms', 96, 1, 'څښتن ته ووایئ یوه نوې سندره ای ټولې نړۍ، سندره ووایئ څښتن ته تاسې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_1.mp3', '', 1761754199, 1761754199),
(39519, 'Psalms 96:2', 'Psalms', 96, 2, 'څښتن ته ووایئ سندره او ستاینه یې د نوم وکړئ اعلان کړئ هره ورځ دا زېری چې نجات یې دی راکړی مونږ ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_2.mp3', '', 1761754199, 1761754199),
(39520, 'Psalms 96:3', 'Psalms', 96, 3, 'قومونو ته اعلان کړئ جلال د هغه ټولو خلکو ته اعلان کړئ د هغه ډېر عجیبه کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_3.mp3', '', 1761754199, 1761754199),
(39521, 'Psalms 96:4', 'Psalms', 96, 4, 'ځکه چې لوی دی څښتن او ډېر لایق دی د ثنا او صفت ټولو خدایانو نه دې زیاته وېره وشي د ده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_4.mp3', '', 1761754199, 1761754199),
(39522, 'Psalms 96:5', 'Psalms', 96, 5, 'نورو قومونو ټول خدایان دي بې‌ګټې بتان خو څښتن دي پیدا کړي اسمانونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_5.mp3', '', 1761754199, 1761754199),
(39523, 'Psalms 96:6', 'Psalms', 96, 6, 'دی راچاپېره جلال او لویي له هغه څخه سپېڅلی کور د هغه ډک دی له قوت او ښایست', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_6.mp3', '', 1761754199, 1761754199),
(39524, 'Psalms 96:7', 'Psalms', 96, 7, 'وکړئ ستاینه د څښتن په ځمکه ټولو خلکو هم ستاینه وکړئ د هغه د جلال او قدرت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_7.mp3', '', 1761754199, 1761754199),
(39525, 'Psalms 96:8', 'Psalms', 96, 8, 'د څښتن د جلالي نوم ستاینه وکړئ د هغه دربار ته راشئ او نذرانه راوړئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_8.mp3', '', 1761754199, 1761754199),
(39526, 'Psalms 96:9', 'Psalms', 96, 9, 'کړئ څښتن ته عبادت په سپېڅلې توګه ای ټولې ځمکې ولړزېږه د هغه په مخکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_9.mp3', '', 1761754199, 1761754199),
(39527, 'Psalms 96:10', 'Psalms', 96, 10, 'تاسو خبر کړئ ټول قومونه د نړۍ چې دی څښتن پاچا! نړۍ یې ټینګه درولې چې خوځیږي نه او قضاوت به د قومونو کړي انصاف باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_10.mp3', '', 1761754199, 1761754199),
(39528, 'Psalms 96:11', 'Psalms', 96, 11, 'پرېږده خوشحاله اسمانونه شي او ځمکه وکړي خوښي شي دریاب په غړمبار دې خپلو ټولو مخلوقاتو سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_11.mp3', '', 1761754199, 1761754199),
(39529, 'Psalms 96:12', 'Psalms', 96, 12, 'شي دې خوشحاله پټي هم ټولو فصلونو سره د ځنګل ټولې ونې به بیا ووهي د خوشحالۍ چیغې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_12.mp3', '', 1761754199, 1761754199),
(39530, 'Psalms 96:13', 'Psalms', 96, 13, 'کله چې راشي د ځمکې قضاوت ته څښتن نو په انصاف سره به وکړي قضاوت د نړۍ او قضاوت د ولسونو عدالت باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms96_verse_13.mp3', '', 1761754199, 1761754199),
(39531, 'Job 39:1', 'Job', 39, 1, 'تا ته پته شته چې کله د غرۀ چېلۍ بچى راوړى؟ ولې تۀ پرې نظر ساتې چې کله هوسۍ بچى راوړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_1.mp3', '', 1761754199, 1761754199),
(39532, 'Job 39:2', 'Job', 39, 2, 'ولې تا ته پته شته چې دا بچى څو مياشتې د هغوئ په ګېډه وى؟ او تا ته د هغه وخت پته شته څۀ چې دا به کله پېدا شى', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_2.mp3', '', 1761754199, 1761754199),
(39533, 'Job 39:3', 'Job', 39, 3, 'کله چې هغوئ د اولاد د پېدا کېدو دپاره کښېنى، او د هغوئ بچى پېدا شى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_3.mp3', '', 1761754199, 1761754199),
(39534, 'Job 39:4', 'Job', 39, 4, 'د هغوئ بچى تکړه شى او په ځنګل کښې لوئيږى، هغوئ ترې نه لاړ شى او واپس ورله نۀ راځى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_4.mp3', '', 1761754199, 1761754199),
(39535, 'Job 39:5', 'Job', 39, 5, 'ځنګلى خرونه چا پرېښې دى چې خوشى لاړ شى؟ دا چا آزاد پرېښى دى چې ګرځى راګرځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_5.mp3', '', 1761754199, 1761754199),
(39536, 'Job 39:6', 'Job', 39, 6, 'ما دا په صحرا کښې پرېښى دى، او د مالګې مُلک مې ورکړے دے چې په کښې اوسيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_6.mp3', '', 1761754199, 1761754199),
(39537, 'Job 39:7', 'Job', 39, 7, 'هغه د ښار د شور نه نفرت کوى، او خرکار ورسره نشته چې په دې باندې آواز وکړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_7.mp3', '', 1761754199, 1761754199),
(39538, 'Job 39:8', 'Job', 39, 8, 'دا غرونو ته ځى چې دا يې د څرن زمکه شى، او هر يو شين بوټے د خوراک دپاره لټوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_8.mp3', '', 1761754199, 1761754199),
(39539, 'Job 39:9', 'Job', 39, 9, 'ولې ځنګلى غوَيے به تا پرېږدى چې کار ترېنه واخلى؟ هغه به ستا په اخور کښې شپه تېره کړى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_9.mp3', '', 1761754199, 1761754199),
(39540, 'Job 39:10', 'Job', 39, 10, 'ولې تۀ يو ځنګلى غوَيے د يوې دپاره تړلے شې؟ دا به ستا دپاره يو پټے يوه کړى څۀ؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_10.mp3', '', 1761754199, 1761754199),
(39541, 'Job 39:11', 'Job', 39, 11, 'ولې تۀ د هغې لوئ طاقت باندې اعتبار کولے شې چې هغه به ستا مدد وکړى؟ تۀ په دې باندې دا يقين کولے شې څۀ چې دا به ستا دپاره کار وکړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_11.mp3', '', 1761754199, 1761754199),
(39542, 'Job 39:12', 'Job', 39, 12, 'تۀ په دې يقين کوې چې دا به واپس راشى، او ستا درمند ته به ګېډى راوړى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_12.mp3', '', 1761754199, 1761754199),
(39543, 'Job 39:13', 'Job', 39, 13, 'د شتر‌مرغ وزر ښائسته کولاو خوريږى، خو دا د زاڼې د وزرو برابر کېدے خو نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_13.mp3', '', 1761754199, 1761754199),
(39544, 'Job 39:14', 'Job', 39, 14, 'شتر‌مرغ خپلې هګۍ د دې دپاره په زمکه پرېږدى، چې ګرمى شى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_14.mp3', '', 1761754199, 1761754199),
(39545, 'Job 39:15', 'Job', 39, 15, 'دا فکر نۀ کوى چې د څۀ پښې لاندې به راشى، او چې يو ځنګلى ځناور به يې ذرې ذرې کړى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_15.mp3', '', 1761754199, 1761754199),
(39546, 'Job 39:16', 'Job', 39, 16, 'دا په خپل بچى باندې داسې ظلم کوى، چې ګنې دا يې خپل نۀ وى، او کۀ مرى نو پرواه يې نۀ ساتى،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_16.mp3', '', 1761754199, 1761754199),
(39547, 'Job 39:17', 'Job', 39, 17, 'ځکه چې خُدائ پاک د هغې نه عقل اخستے دے، او هيڅ پوهه يې نۀ ده ورکړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_17.mp3', '', 1761754199, 1761754199),
(39548, 'Job 39:18', 'Job', 39, 18, 'خو کله چې پاڅى او منډه کړى، نو بيا څوک چې په آس ناست هم وى د دې نه مخکښې کېدے نۀ شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_18.mp3', '', 1761754199, 1761754199),
(39549, 'Job 39:19', 'Job', 39, 19, 'ولې آس له طاقت تا ورکړے دے؟ د هغۀ په څټ باندې وېښتۀ تا پېدا کړى دى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_19.mp3', '', 1761754199, 1761754199),
(39550, 'Job 39:20', 'Job', 39, 20, 'د قحطۍ مُولخانو په شان د دې ټوپ تا جوړ کړے دے؟ او يا د دې هغه د رُعب والا آوازونه تا جوړ کړى دى څۀ چې خلق يروى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_20.mp3', '', 1761754199, 1761754199),
(39551, 'Job 39:21', 'Job', 39, 21, 'دا په پښه باندې زمکه ټکوى او په خپل طاقت په هغه وخت خوشحاليږى چې د جنګ دپاره ولېږلے شى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_21.mp3', '', 1761754199, 1761754199),
(39552, 'Job 39:22', 'Job', 39, 22, 'دا يرې پورې خندا کوى او نۀ بې‌حوصلې کيږى، او د تُورې نه نۀ شاته کيږى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_22.mp3', '', 1761754199, 1761754199),
(39553, 'Job 39:23', 'Job', 39, 23, 'په دې باندې سورلۍ سره د غشو تيلۍ ځلېدونکې نېزه او وړه نېزه هم آواز پېدا کوى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_23.mp3', '', 1761754199, 1761754199),
(39554, 'Job 39:24', 'Job', 39, 24, 'د جوش او د غصې د وجې دا په تېزۍ سره ځى، دا د بيګل د غږېدو پورې صبر نۀ شى کولے.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_24.mp3', '', 1761754199, 1761754199),
(39555, 'Job 39:25', 'Job', 39, 25, 'کله چې بيګل وغږيږى نو آس يو هڼ آواز وکړى. د لرې ځائ نه هغۀ له د جنګ بوئ ورځى، د جنګى مشرانو د تندر په شان آواز او چغې اورى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_25.mp3', '', 1761754199, 1761754199),
(39556, 'Job 39:26', 'Job', 39, 26, 'ولې باښه ستا د عقل په وجه الوځى، چې خپل وزر خوارۀ کړى او د جنوب طرف ته والوځى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_26.mp3', '', 1761754199, 1761754199),
(39557, 'Job 39:27', 'Job', 39, 27, 'باز ستا په حُکم بره خېژى او په اوچت ځائ خپله جاله جوړوى؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_27.mp3', '', 1761754199, 1761754199),
(39558, 'Job 39:28', 'Job', 39, 28, 'دا په اوچت ګټ باندې اوسيږى او خپل کور جوړوى او د ګټ په سر باندې په يو محفوظ ځائ کښې شپه تېروى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_28.mp3', '', 1761754199, 1761754199),
(39559, 'Job 39:29', 'Job', 39, 29, 'د هغه ځائ نه يې په ښکار باندې نظر وى، او د هغۀ سترګې ښکار د لرې ځائ نه وينى.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_29.mp3', '', 1761754199, 1761754199),
(39560, 'Job 39:30', 'Job', 39, 30, 'د دې بچى وينه څښى، او چې په کوم ځائ کښې مرداره وى، نو هغه په هغه ځائ کښې حاضر وى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/job39_verse_30.mp3', '', 1761754199, 1761754199),
(39561, 'Nehemiah 8:1', 'Nehemiah', 8, 1, 'په اوومه میاشت د اسراییلو قوم ټول په خپلو ښارونو کې ځای په ځای شول. د همدې میاشتې په لومړۍ ورځ هغوی ټول په اورشلیم کې د اوبو د دروازې مخې ته په حوېلۍ کې سره راټول شول. هغوی د عزرا څخه چې د شریعت عالم ؤ، وغوښتل چې د تورات کتاب چې څښتن د موسی په وسیله اسراییلو ته ورکړی ؤ، راوړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_1.mp3', '', 1761754199, 1761754199),
(39562, 'Nehemiah 8:2', 'Nehemiah', 8, 2, 'نو عزرا هغه کتاب هغه ځای ته راوړ چې خلک په کې راټول شوي وو، یعنې سړي، ښځې او هغه ماشومان چې په داسې عمر کې وو چې د پوهېدلو توان یې درلود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_2.mp3', '', 1761754199, 1761754199),
(39563, 'Nehemiah 8:3', 'Nehemiah', 8, 3, 'عزرا دروازې ته په مخامخ حوېلۍ کې د سهار وختي څخه تر غرمې پورې هغوی ته تورات ولوست او هغوی ټولو ورته په غور سره غوږ نیولی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_3.mp3', '', 1761754199, 1761754199),
(39564, 'Nehemiah 8:4', 'Nehemiah', 8, 4, 'عزرا د لرګي په منبر باندې چې د همدې مقصد دپاره جوړ شوی ؤ، ولاړ ؤ. د هغه ښي لاس ته متتیا، شمع، عنایا، اوریا، حلقیا او معسیا او چپ لاس ته یې فدایا، میشاییل، ملکیا، حاشوم، حشبدانه، زکریا او مشلام ولاړ وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_4.mp3', '', 1761754199, 1761754199),
(39565, 'Nehemiah 8:5', 'Nehemiah', 8, 5, 'عزرا په یو داسې لوړ ځای کې ولاړ ؤ چې هرچا لیدلی شو. کله چې هغه کتاب پرانیست، هغوی ټول ودرېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_5.mp3', '', 1761754199, 1761754199),
(39566, 'Nehemiah 8:6', 'Nehemiah', 8, 6, 'عزرا لوی څښتن خدای ته ثنا وویله او ټول قوم خپل لاسونه پورته کړل او په ځواب کې یې وویل: «آمین! آمین!» هغوی په سجده شول او د څښتن عبادت یې وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_6.mp3', '', 1761754199, 1761754199),
(39567, 'Nehemiah 8:7', 'Nehemiah', 8, 7, 'وروسته بیا هغوی پاڅېدل او په خپلو ځایونو کې ودرېدل او دغو لاویانو ورته د تورات کتاب بیان کړ: یشوع، باني، شربیا، یامین، عقوب، شبتای، هودیه، معسیا، قلیطا، عزریا، یوزاباد، حانان او فلایا.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_7.mp3', '', 1761754199, 1761754199),
(39568, 'Nehemiah 8:8', 'Nehemiah', 8, 8, 'هغوی د خدای د تورات کتاب په لوړ اواز لوسته او هغه یې تشریح کاوه، ترڅو خلک پرې پوه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_8.mp3', '', 1761754199, 1761754199),
(39569, 'Nehemiah 8:9', 'Nehemiah', 8, 9, 'کله چې خلکو ته شریعت لوستل کېده، هغوی په ژړا پیل وکړ. نو نحمیا والي، عزرا کاهن او د شریعت عالم او هغو لاویانو چې خلکو ته یې شریعت تشریح کاوه، ټولو خلکو ته وویل: «دا ورځ ستاسو د څښتن خدای سپېڅلې ورځ ده. نو تاسو ویر او ژړا مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_9.mp3', '', 1761754199, 1761754199),
(39570, 'Nehemiah 8:10', 'Nehemiah', 8, 10, 'اوس خپلو کورونو ته لاړ شئ او جشن ونیسئ. د خپلو خوندورو خوړو او شرابو څخه هغه چاته چې نه یې لري د هغوی برخه ورکړئ. نن ورځ زمونږ د څښتن دپاره یوه سپېڅلې ورځ ده، نو مه خفه کېږئ. د څښتن خوشحالي ستاسو قوت دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_10.mp3', '', 1761754199, 1761754199),
(39571, 'Nehemiah 8:11', 'Nehemiah', 8, 11, 'لاویانو هم خلک ارام کړل او هغوی ته یې وویل: «غلي شئ! نن ورځ یوه سپېڅلې ورځ ده، نو مه ژاړئ او مه خفه کېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_11.mp3', '', 1761754199, 1761754199),
(39572, 'Nehemiah 8:12', 'Nehemiah', 8, 12, 'نو ټول خلک خپلو کورونو ته لاړل. هغوی په ډېره خوشحالۍ سره وخوړل او ویې څښل او څه چې یې درلودل، د هغو څخه یې نورو ته هم د هغوی برخه ورولېږله، ځکه څه چې هغوی ته لوستل شوي وو، ورباندې پوه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_12.mp3', '', 1761754199, 1761754199),
(39573, 'Nehemiah 8:13', 'Nehemiah', 8, 13, 'یوه ورځ وروسته د ټولو طایفو مشران د کاهنانو او لاویانو سره یوځای عزرا ته ورغلل چې هغوی د تورات حکمونه زده کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_13.mp3', '', 1761754199, 1761754199),
(39574, 'Nehemiah 8:14', 'Nehemiah', 8, 14, 'هغوی په دې پوه شول چې په شریعت کې لیکل شوي دي چې څښتن د موسی په وسیله حکم کړی ؤ چې په اوومه میاشت چې هغوی اختر لمانځي، باید په جونګړو کې واوسیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_14.mp3', '', 1761754199, 1761754199),
(39575, 'Nehemiah 8:15', 'Nehemiah', 8, 15, 'دا هغه حکم ؤ چې هغوی باید په اورشلیم او نورو ښارګوټو کې اعلان وکړي: «غرونو ته لاړ شئ او د زیتونو، ځنګلي زیتون، اس، خرما او نورو ونو څانګې راوړئ چې په شریعت کې د لیکل شویو لارښوونو سره سم د هغو څخه جونګړې جوړې کړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_15.mp3', '', 1761754199, 1761754199),
(39576, 'Nehemiah 8:16', 'Nehemiah', 8, 16, 'نو خلکو د ونو څانګې راوړلې او د خپلو کوټو په بامونو، په خپلو حوېلیو، د خدای د کور په حویلۍ او د اوبو د دروازې او د افرایم د دروازې په عمومي میدان کې یې ورڅخه جونګړې جوړې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_16.mp3', '', 1761754199, 1761754199),
(39577, 'Nehemiah 8:17', 'Nehemiah', 8, 17, 'هغو ټولو خلکو چې د اسیرتوب څخه بېرته راغلي وو، جونګړې جوړې کړې او په هغو کې اوسېدل. هغوی ټول ډېر خوشحاله وو، ځکه چې د نون د زوی یوشع د زمانې څخه تر هغې ورځې پورې اسراییلیانو په دې ډول جشن نه ؤ لمانځلی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_17.mp3', '', 1761754199, 1761754199),
(39578, 'Nehemiah 8:18', 'Nehemiah', 8, 18, 'د اختر د لومړۍ ورځې څخه تر وروستنۍ ورځې پورې عزرا هره ورځ د خدای د تورات یوه برخه په لوړ اواز لوستله. هغوی دا اختر اووه ورځې ولمانځه او د شریعت سره سم په اتمه ورځ نوموړي مراسم په دعا او عبادت سره پای ته ورسېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nehemiah8_verse_18.mp3', '', 1761754199, 1761754199),
(39579, 'Amos 4:1', 'Amos', 4, 1, 'ای د سامرې مېرمنو چې د باشان د غواګانو په شان چاغې شوې یئ، د کمزورو خلکو سره بد چلند کوئ، په غریبانو باندې ظلم کوئ او د خپلو مېړونو څخه غواړئ چې تاسو ته شراب راوړي، دې خبرو ته غوږ ونیسئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_1.mp3', '', 1761754199, 1761754199),
(39580, 'Amos 4:2', 'Amos', 4, 2, 'څښتن تعالی چې سپېڅلی ذات دی، قسم خوړلی دی: «هغه وخت راروان دی چې هغوی به په تاسو کې چنګک واچوي او تاسو به لکه د ماهیانو په شان راکاږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_2.mp3', '', 1761754199, 1761754199),
(39581, 'Amos 4:3', 'Amos', 4, 3, 'تاسو هر یو به د دېوال نژدې سوریو کې راښکل کېږئ او دباندې حرمون ته به غورځول کېږئ.» دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_3.mp3', '', 1761754199, 1761754199),
(39582, 'Amos 4:4', 'Amos', 4, 4, 'ای د اسراییلو خلکو، نو بیا لاړ شئ او په بیت‌ییل کې ګناه وکړئ! جلجال ته لاړ شئ او څومره چې کولای شئ ګناه وکړئ! هر سهار خپلې قربانۍ او په هره درېمه ورځ خپل عشر راوړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_4.mp3', '', 1761754199, 1761754199),
(39583, 'Amos 4:5', 'Amos', 4, 5, 'لاړ شئ او خدای ته د شکرانې ډوډۍ وړاندې کړئ او تاسو چې د خپلې خوښې کومې اضافي نذرانې راوړئ، نو د هغو په هکله لافې ووهئ! ځکه چې دا کار ستاسو اسراییلیانو خوښ دی. دا هغه څه دي چې څښتن تعالی ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_5.mp3', '', 1761754199, 1761754199),
(39584, 'Amos 4:6', 'Amos', 4, 6, 'دا زه وم چې ستاسو په ټولو ښارونو باندې مې لوږه راوستله او په هر ځای کې مې قحطي راوستله، خو بیاهم تاسو ماته رجوع ونه کړه. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_6.mp3', '', 1761754199, 1761754199),
(39585, 'Amos 4:7', 'Amos', 4, 7, 'کله چې ستاسو فصلونو ته د باران سخته اړتیا وه، نو ما باران بند کړ. په یو ښار باندې مې باران ووراوه او په بل ښار باندې مې بند کړ. په یو پټي باندې باران واورېده او په بل پټی چې باران ونه واورېده وچ شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_7.mp3', '', 1761754199, 1761754199),
(39586, 'Amos 4:8', 'Amos', 4, 8, 'د څو ښارونو تندې وهلي خلک به ښار په ښار د اوبو پیدا کولو په هیله ګرځېدل، خو هلته به د څښلو دپاره زیاتې اوبه نه وې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_8.mp3', '', 1761754199, 1761754199),
(39587, 'Amos 4:9', 'Amos', 4, 9, 'ما یو سوځوونکی باد او مرض نازل کړ چې ستاسو فصلونه وچ شي. ستاسو ټول باغونه او تاکونه، د انځرو او د زیتونو ونې ملخانو وخوړلې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_9.mp3', '', 1761754199, 1761754199),
(39588, 'Amos 4:10', 'Amos', 4, 10, 'کومه بلا چې ما په مصر باندې راوستې وه، هغه مې په تاسو باندې راوستله. ستاسو ځوانان مې په جنګ کې ووژل او اسونه مې درڅخه واخیستل. ستاسو پوزې مې په خېمو کې د مړو د بوی نه ډکې کړلې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_10.mp3', '', 1761754199, 1761754199),
(39589, 'Amos 4:11', 'Amos', 4, 11, 'ما ستاسو ځینې خلک د سدوم او عموره د خلکو په شان تباه کړل. ستاسو نه چې کوم خلک ژوندي پاتې شوي وو، نو هغوی د سوځېدلي لرګي په شان وو چې د اور نه راویستل شوي وو. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_11.mp3', '', 1761754199, 1761754199),
(39590, 'Amos 4:12', 'Amos', 4, 12, 'نو ای د اسراییلو خلکو، زه تاسو ته سزا درکوم. څرنګه چې زه دا کار کوم، نو زما قضاوت ته تیار شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_12.mp3', '', 1761754199, 1761754199),
(39591, 'Amos 4:13', 'Amos', 4, 13, 'دا هغه ذات دی چې جوړ کړي یې دي غرونه او پیدا کړي یې دي بادونه هغه خبروي انسانان خپلو خیالونو نه هغه ورځ بدلوي شپې باندې هغه ګرځي د ځمکې په اوچتو ځایو د هغه نوم دی مطلق قادر څښتن خدای', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/amos4_verse_13.mp3', '', 1761754199, 1761754199),
(39592, 'Psalms 75:1', 'Psalms', 75, 1, 'مونږه ستا شکر کوو خدایه شکر کوو مونږه ځکه چې نژدې یې راته بیانوي خلک ستا عجیبه کارونه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_1.mp3', '', 1761754199, 1761754199),
(39593, 'Psalms 75:2', 'Psalms', 75, 2, 'وایي خدای چې ما ټاکلی قضاوت دپاره وخت دی او په انصاف سره به کړم قضاوت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_2.mp3', '', 1761754199, 1761754199),
(39594, 'Psalms 75:3', 'Psalms', 75, 3, 'که څه هم هر ژوندی موجود به رېږدي او ځمکه به هم لړزیږي زه به یې وساتمه ستنې ټینګې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_3.mp3', '', 1761754199, 1761754199),
(39595, 'Psalms 75:4', 'Psalms', 75, 4, 'لاپو وهونکو ته دا وایم چې نه دې وهي لافې امر کوم په بدکارانو چې غرور دې نه کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_4.mp3', '', 1761754199, 1761754199),
(39596, 'Psalms 75:5', 'Psalms', 75, 5, 'هغوی ته وایم چې مغرور مه اوسئ د سرکښۍ په سبب بس کړئ د غرور خبرې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_5.mp3', '', 1761754199, 1761754199),
(39597, 'Psalms 75:6', 'Psalms', 75, 6, 'سرلوړي نه راځي له شرقه یا له غربه ځینې او نه له دښتې او بیابانه ځینې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_6.mp3', '', 1761754199, 1761754199),
(39598, 'Psalms 75:7', 'Psalms', 75, 7, 'بلکې دا خدای دی چې کوي قضاوت ورکوي یو ته سرلوړي بل ته ذلت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_7.mp3', '', 1761754199, 1761754199),
(39599, 'Psalms 75:8', 'Psalms', 75, 8, 'څښتن نیولې ده پیاله په لاس کې چې کړې یې ډکه د قهر له ترخو شرابو چې اچوي یې څښتن او ټول بدکاران یې څښي باید یې وڅښي بدکاران تر اخري څاڅکي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_8.mp3', '', 1761754199, 1761754199),
(39600, 'Psalms 75:9', 'Psalms', 75, 9, 'خو زه به هېڅکله بس نه کړمه خبرې د یعقوب د خدای په هکله او ورته وایمه سندرې به زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_9.mp3', '', 1761754199, 1761754199),
(39601, 'Psalms 75:10', 'Psalms', 75, 10, 'هغه به مات کړي ټول قوت د بدکارانو خو قوت به زیات شي د نېکانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms75_verse_10.mp3', '', 1761754199, 1761754199),
(39602, 'Joshua 16:1', 'Joshua', 16, 1, 'د هغې ځمکې جنوبي سرحد چې د یوسف اولادې ته ورکړل شوې ده، اریحا ته نژدې د اردن د سیند څخه پیل شوی دی یعنې د اریحا د چینو د ختیځ څخه پیل شوی او د دښتې څخه تېر شوی او د اریحا څخه د بیت ییل تر غرنۍ سیمې پورې رسېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_1.mp3', '', 1761754199, 1761754199),
(39603, 'Joshua 16:2', 'Joshua', 16, 2, 'هغه د بیت ییل څخه لوز ته راوتلی دی او عطاروت ادار ته چې ارکیان په کې اوسېدل، وتلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_2.mp3', '', 1761754199, 1761754199),
(39604, 'Joshua 16:3', 'Joshua', 16, 3, 'بیا د ښکتني بیت حورون پورې په لوېدیځ کې د یفلیطیانو سیمې ته غزېدلی دی. د هغه ځای څخه جازر ته وتلی او د مدیترانې په بحیره کې ختم شوی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_3.mp3', '', 1761754199, 1761754199),
(39605, 'Joshua 16:4', 'Joshua', 16, 4, 'د یوسف اولادې یعنې د افرایم او لوېدیځې منسي قبیلو دا ځمکه د خپل ملکیت په توګه تر لاسه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_4.mp3', '', 1761754199, 1761754199),
(39606, 'Joshua 16:5', 'Joshua', 16, 5, 'دا سیمه د طایفې له مخې د افرایم سیمه وه: د هغوی د ځمکې سرحد د عطاروت ادار څخه چې په ختیځ کې ؤ پورتني بیت حورون ته رسېده', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_5.mp3', '', 1761754199, 1761754199),
(39607, 'Joshua 16:6', 'Joshua', 16, 6, 'او د مدیترانې بحیرې ته تللی دی. د مکمیته څخه چې په شمال کې ؤ، ختیځ خواته تعنت شیلوه ته راګرځېدلی او د هغه ځای په ختیځ کې تېر شوی او یانواح ته تللی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_6.mp3', '', 1761754199, 1761754199),
(39608, 'Joshua 16:7', 'Joshua', 16, 7, 'بیا دا سرحد د یانواح څخه عطاروت او نعره ته راښکته شوی، د اریحا سره نښتی او د اردن سیند ته راوتلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_7.mp3', '', 1761754199, 1761754199),
(39609, 'Joshua 16:8', 'Joshua', 16, 8, 'د تفوح څخه دا سرحد لوېدیځ خواته د قانه خوړ ته تللی او د مدیترانې په بحیره کې ختم شوی دی. دا هغه ځمکه وه چې د ملکیت په توګه د افرایم قبیلې ته طایفه په طایفه ورکړل شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_8.mp3', '', 1761754199, 1761754199),
(39610, 'Joshua 16:9', 'Joshua', 16, 9, 'په دې کې ځینې ښارګوټي او کلي هم شامل وو چې د منسي د قبیلې په خاوره کې وو، خو هغه افرایم ته ورکړل شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua16_verse_9.mp3', '', 1761754199, 1761754199);